def transform(grid):
    shs=extract(grid)
    ys=[i for i in range(len(grid)) if any(grid[i])]
    xs=[j for j in range(len(grid[0])) if any(row[j] for row in grid)]
    rowspan=max(ys)-min(ys); colspan=max(xs)-min(xs)
    if colspan>=rowspan:
        hh=max(len(s) for s in shs); ww=sum(len(s[0]) for s in shs)
        res=[[0]*ww for _ in range(hh)]; off=0
        for s in shs:
            for i,row in enumerate(s):
                for j,v in enumerate(row): res[i][off+j]=v
            off+=len(s[0])
    else:
        hh=sum(len(s) for s in shs); ww=max(len(s[0]) for s in shs)
        res=[[0]*ww for _ in range(hh)]; off=0
        for s in shs:
            for i,row in enumerate(s):
                for j,v in enumerate(row): res[off+i][j]=v
            off+=len(s)
    return res

