def extract(grid):
    h=len(grid); w=len(grid[0])
    cells={}
    for i in range(h):
        for j in range(w):
            if grid[i][j]: cells.setdefault(grid[i][j],[]).append((i,j))
    order=sorted(cells, key=lambda c: min(p[1] for p in cells[c]))
    shs=[]
    for c in order:
        ps=cells[c]
        t=min(p[0] for p in ps); b=max(p[0] for p in ps)
        l=min(p[1] for p in ps); r=max(p[1] for p in ps)
        shs.append([[grid[i][j] if grid[i][j]==c else 0 for j in range(l,r+1)] for i in range(t,b+1)])
    return shs

